CREATE TABLE IF NOT EXISTS shop_invoice(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL UNIQUE,requested_by BIGINT NOT NULL,title_kind VARCHAR(20) NOT NULL,title VARCHAR(150) NOT NULL,tax_number VARCHAR(30) NULL,email VARCHAR(150) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'requested',requested_amount BIGINT NOT NULL,issued_amount BIGINT NOT NULL DEFAULT 0,note VARCHAR(500) NULL,due_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_invoice_file(id BIGINT PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT NOT NULL,path VARCHAR(150) NOT NULL UNIQUE,original_name VARCHAR(200) NOT NULL,invoice_number VARCHAR(100) NOT NULL,amount BIGINT NOT NULL,file_kind VARCHAR(20) NOT NULL,note VARCHAR(500) NOT NULL,operator_name VARCHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
